def _dinheiro(v) -> str:
    try:
        n = float(v)
    except (TypeError, ValueError):
        return str(v)
    if n >= 1_000_000:
        x = f"{n / 1_000_000:.2f}".rstrip("0").rstrip(".").replace(".", ",")
        return f"R$ {x} {'milhões' if n >= 2_000_000 else 'milhão'}"
    return "R$ " + f"{n:,.0f}".replace(",", ".")

