def descricao_do_imovel(ficha: dict) -> str:
    """"o apartamento no Life Parque Dez" / "a casa no Aleixo": para ele saber de qual imóvel ela está falando."""
    tipo = (ficha.get("tipo") or "imóvel").split("/")[0].lower()
    artigo = "a" if tipo.startswith(("casa", "sala", "loja", "cobertura", "chácara")) else "o"
    onde = ficha.get("condominio") or ficha.get("bairro")
    return f"{artigo} {tipo}" + (f" no {onde}" if onde else "")

condominio.py:escolher.codigo:
def escolher(candidatos: list[dict]) -> tuple[str, dict | None]:
    """('ligar', o condomínio) | ('confirmar', o candidato) | ('novo', None)."""
    if not candidatos:
        return "novo", None
    melhor = candidatos[0]
    segundo = candidatos[1] if len(candidatos) > 1 else None
    folga = (float(melhor["parecenca"]) - float(segundo["parecenca"])) if segundo else 1.0
    if melhor["faixa"] <= 3 and (segundo is None or segundo["faixa"] > melhor["faixa"] or folga >= 0.1):
        return "ligar", melhor
    if melhor["faixa"] == 4 and float(melhor["parecenca"]) >= 0.6 and folga >= 0.05:
        return "ligar", melhor
    return "confirmar", melhor

